    40→class WiFiDirectManager(
    41→    private val context: Context,
    42→    private val manager: WifiP2pManager,
    43→    private val channel: WifiP2pManager.Channel,
    44→) {
    45→
    46→    companion object {
    47→        private const val SERVICE_TYPE = "_entercomm._tcp"
    48→        private const val SERVICE_INSTANCE = "EnterCommBikeIntercom"
    49→    }
    50→
    51→    private var isReceiverRegistered = false
    52→
    53→    /**
    54→     * Check if required WiFi Direct permissions are granted
    55→     */
    56→    private fun hasWifiDirectPermission(): Boolean {
    57→        // On Android 13+, NEARBY_WIFI_DEVICES is required
    58→        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
    59→            if (ContextCompat.checkSelfPermission(context, Manifest.permission.NEARBY_WIFI_DEVICES)
    60→                != PackageManager.PERMISSION_GRANTED
    61→            ) {
    62→                return false
    63→            }
    64→        }
    65→        // On all versions, ACCESS_FINE_LOCATION is required for WiFi Direct
    66→        return ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) ==
    67→            PackageManager.PERMISSION_GRANTED
    68→    }
    69→
    70→    @SuppressLint("MissingPermission") // Permission is checked in hasWifiDirectPermission()
    71→    private fun requestPeersIfPermitted() {
    72→        if (!hasWifiDirectPermission()) {
    73→            logW { "Missing permission to request peers" }
    74→            return
    75→        }
    76→        manager.requestPeers(channel) { peers ->
    77→            val peerList = peers.deviceList.toList()
    78→            _availablePeers.value = peerList
    79→            eventChannel.trySend(WiFiDirectEvent.PeersChanged(peerList))
    80→            logD { "Peers changed: ${peerList.size} devices found" }
    81→        }
    82→    }
    83→
    84→    private val _connectedPeers = MutableStateFlow<List<PeerDevice>>(emptyList())
    85→    val connectedPeers: StateFlow<List<PeerDevice>> = _connectedPeers.asStateFlow()
    86→
    87→    private val _isDiscovering = MutableStateFlow(false)
    88→    val isDiscovering: StateFlow<Boolean> = _isDiscovering.asStateFlow()
    89→
    90→    private val _connectionInfo = MutableStateFlow<WifiP2pInfo?>(null)
    91→    val connectionInfo: StateFlow<WifiP2pInfo?> = _connectionInfo.asStateFlow()
    92→
    93→    private val _availablePeers = MutableStateFlow<List<WifiP2pDevice>>(emptyList())
    94→    val availablePeers: StateFlow<List<WifiP2pDevice>> = _availablePeers.asStateFlow()
    95→
    96→    private val eventChannel = Channel<WiFiDirectEvent>(Channel.UNLIMITED)
    97→
    98→    private val receiver = object : BroadcastReceiver() {
    99→        override fun onReceive(context: Context, intent: Intent) {
   100→            when (intent.action) {
   101→                WifiP2pManager.WIFI_P2P_STATE_CHANGED_ACTION -> {
   102→                    val state = intent.getIntExtra(WifiP2pManager.EXTRA_WIFI_STATE, -1)
   103→                    if (state == WifiP2pManager.WIFI_P2P_STATE_ENABLED) {
   104→                        eventChannel.trySend(WiFiDirectEvent.WiFiP2pEnabled)
   105→                        logD { "WiFi P2P enabled" }
   106→                    } else {
   107→                        eventChannel.trySend(WiFiDirectEvent.WiFiP2pDisabled)
   108→                        logD { "WiFi P2P disabled" }
   109→                    }
   110→                }
   111→
   112→                WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION -> {
   113→                    requestPeersIfPermitted()
   114→                }
   115→
   116→                WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION -> {
   117→                    val info = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
   118→                        intent.getParcelableExtra(WifiP2pManager.EXTRA_WIFI_P2P_INFO, WifiP2pInfo::class.java)
   119→                    } else {
   120→                        @Suppress("DEPRECATION")
   121→                        intent.getParcelableExtra(WifiP2pManager.EXTRA_WIFI_P2P_INFO)
   122→                    }
   123→                    _connectionInfo.value = info
   124→                    eventChannel.trySend(WiFiDirectEvent.ConnectionChanged(info))
   125→
   126→                    if (info?.groupFormed == true) {
   127→                        logD { "Group formed. Group Owner: ${info.isGroupOwner}" }
   128→                        requestGroupInfo()
   129→                    }
   130→                }
   131→
   132→                WifiP2pManager.WIFI_P2P_THIS_DEVICE_CHANGED_ACTION -> {
   133→                    val device = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
   134→                        intent.getParcelableExtra(WifiP2pManager.EXTRA_WIFI_P2P_DEVICE, WifiP2pDevice::class.java)
   135→                    } else {
   136→                        @Suppress("DEPRECATION")
   137→                        intent.getParcelableExtra(WifiP2pManager.EXTRA_WIFI_P2P_DEVICE)
   138→                    }
   139→                    eventChannel.trySend(WiFiDirectEvent.DeviceChanged(device))
   140→                    logD { "This device changed: ${device?.deviceName}" }
   141→                }
   142→            }
   143→        }
   144→    }
   145→
   146→    private val intentFilter = IntentFilter().apply {
   147→        addAction(WifiP2pManager.WIFI_P2P_STATE_CHANGED_ACTION)
   148→        addAction(WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION)
   149→        addAction(WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION)
   150→        addAction(WifiP2pManager.WIFI_P2P_THIS_DEVICE_CHANGED_ACTION)
   151→    }
   152→
   153→    fun initialize() {
   154→        if (!isReceiverRegistered) {
   155→            context.registerReceiver(receiver, intentFilter)
   156→            isReceiverRegistered = true
   157→            logD { "WiFiDirectManager initialized" }
   158→        } else {
   159→            logD { "WiFiDirectManager already initialized" }
   160→        }
   161→    }
   162→
   163→    fun cleanup() {
   164→        try {
   165→            if (isReceiverRegistered) {
   166→                context.unregisterReceiver(receiver)
   167→                isReceiverRegistered = false
   168→            }
   169→            stopDiscovery()
   170→            disconnect()
   171→        } catch (e: IllegalArgumentException) {
   172→            logW { "Receiver was not registered" }
   173→            isReceiverRegistered = false
   174→        } catch (e: Exception) {
   175→            logE({ "Error during cleanup" }, e)
   176→        }
   177→    }
   178→
   179→    @SuppressLint("MissingPermission") // Permission is checked in hasWifiDirectPermission() above
   180→    fun startDiscovery() {
   181→        if (!hasWifiDirectPermission()) {
   182→            val message = "WiFi Direct permissions not granted"
   183→            logE { message }
   184→            eventChannel.trySend(WiFiDirectEvent.Error(message))
   185→            return
   186→        }
   187→
   188→        manager.discoverPeers(
   189→            channel,
   190→            object : ActionListener {
   191→                override fun onSuccess() {
   192→                    _isDiscovering.value = true
   193→                    logD { "Discovery started successfully" }
   194→                }
   195→
   196→                override fun onFailure(reason: Int) {
   197→                    _isDiscovering.value = false
   198→                    val message = "Discovery failed: ${getErrorMessage(reason)}"
   199→                    logE { message }
   200→                    eventChannel.trySend(WiFiDirectEvent.Error(message))
   201→                }
   202→            },
   203→        )
   204→    }
   205→
   206→    fun stopDiscovery() {
   207→        manager.stopPeerDiscovery(
   208→            channel,
   209→            object : ActionListener {
   210→                override fun onSuccess() {
   211→                    _isDiscovering.value = false
   212→                    logD { "Discovery stopped successfully" }
   213→                }
   214→
   215→                override fun onFailure(reason: Int) {
   216→                    logE { "Failed to stop discovery: ${getErrorMessage(reason)}" }
   217→                }
   218→            },
   219→        )
   220→    }
